WHERE user_id = #{userId}
ORDER BY watched_at DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE watch_history
SET progress_seconds = #{progressSeconds}, watched_at = NOW()
WHERE user_id = #{userId} AND video_id = #{videoId}

